#!/usr/bin/env python3
"""
Parallel TF-IDF Implementation

Provides parallel index building and batch search while preserving
identical results to the sequential baseline.
"""

from __future__ import annotations

import itertools
import math
import os
import time
from collections import defaultdict
from concurrent.futures import ProcessPoolExecutor
from dataclasses import dataclass
from heapq import nlargest

from document_generator import Document
from sequential import SearchResult, TFIDFIndex, compute_term_frequencies, tokenize

# ----------------------------------------------------------------------------
# Data structures
# ----------------------------------------------------------------------------


@dataclass
class ParallelIndexingResult:
    """Result from parallel index building."""

    index: TFIDFIndex
    elapsed_time: float
    num_documents: int
    vocabulary_size: int


# ----------------------------------------------------------------------------
# Internal helpers
# ----------------------------------------------------------------------------


def _normalize_workers(num_workers: int | None, item_count: int) -> int:
    if num_workers is None or num_workers <= 0:
        num_workers = os.cpu_count() or 1
    if item_count <= 0:
        return 1
    return max(1, min(num_workers, item_count))


def _chunk_sequence(items: list, chunk_size: int) -> list[list]:
    chunk_size = max(1, chunk_size)
    return [items[i : i + chunk_size] for i in range(0, len(items), chunk_size)]


def _process_documents_chunk(documents: list[Document]) -> tuple[dict[int, dict[str, float]], dict[str, int]]:
    """
    Tokenize documents and compute term frequencies + local document frequencies.

    Returns:
        doc_term_freqs: doc_id -> term frequency dict
        df_counts: term -> document frequency count (within this chunk)
    """
    doc_term_freqs: dict[int, dict[str, float]] = {}
    df_counts: dict[str, int] = defaultdict(int)

    for doc in documents:
        text = f"{doc.title} {doc.content}"
        tokens = tokenize(text)
        tf = compute_term_frequencies(tokens)
        doc_term_freqs[doc.doc_id] = tf
        if tf:
            for term in tf.keys():
                df_counts[term] += 1

    return doc_term_freqs, df_counts


_WORKER_IDF: dict[str, float] | None = None


def _init_tfidf_worker(idf: dict[str, float]) -> None:
    global _WORKER_IDF
    _WORKER_IDF = idf


def _build_postings_chunk(doc_term_freqs: dict[int, dict[str, float]], idf: dict[str, float]) -> tuple[dict[str, list[tuple[int, float]]], dict[int, dict[str, float]], dict[int, float]]:
    local_postings: dict[str, list[tuple[int, float]]] = defaultdict(list)
    local_doc_vectors: dict[int, dict[str, float]] = {}
    local_doc_norms: dict[int, float] = {}

    for doc_id, tf_dict in doc_term_freqs.items():
        doc_vector: dict[str, float] = {}
        norm_squared = 0.0
        for term, tf in tf_dict.items():
            tfidf = tf * idf[term]
            doc_vector[term] = tfidf
            norm_squared += tfidf * tfidf
            local_postings[term].append((doc_id, tfidf))
        local_doc_vectors[doc_id] = doc_vector
        local_doc_norms[doc_id] = math.sqrt(norm_squared)

    return local_postings, local_doc_vectors, local_doc_norms


def _build_postings_chunk_worker(doc_term_freqs: dict[int, dict[str, float]]) -> tuple[dict[str, list[tuple[int, float]]], dict[int, dict[str, float]], dict[int, float]]:
    if _WORKER_IDF is None:
        raise RuntimeError("Worker IDF not initialized")
    return _build_postings_chunk(doc_term_freqs, _WORKER_IDF)


_WORKER_INDEX: TFIDFIndex | None = None
_WORKER_DOC_TITLES: dict[int, str] | None = None


def _init_search_worker(index: TFIDFIndex, doc_titles: dict[int, str]) -> None:
    global _WORKER_INDEX, _WORKER_DOC_TITLES
    _WORKER_INDEX = index
    _WORKER_DOC_TITLES = doc_titles


def _search_single(query: str, index: TFIDFIndex, top_k: int, doc_titles: dict[int, str]) -> list[SearchResult]:
    query_tokens = tokenize(query)
    if not query_tokens:
        return []

    query_tf = compute_term_frequencies(query_tokens)

    query_vector: dict[str, float] = {}
    query_norm_squared = 0.0
    for term, tf in query_tf.items():
        if term in index.idf:
            tfidf = tf * index.idf[term]
            query_vector[term] = tfidf
            query_norm_squared += tfidf * tfidf

    if not query_vector:
        return []

    query_norm = math.sqrt(query_norm_squared)

    candidate_docs = set()
    for term in query_vector:
        if term in index.inverted_index:
            for doc_id, _ in index.inverted_index[term]:
                candidate_docs.add(doc_id)

    scores: list[tuple[int, float]] = []
    for doc_id in candidate_docs:
        doc_vector = index.doc_vectors.get(doc_id, {})
        doc_norm = index.doc_norms.get(doc_id, 0.0)
        if doc_norm == 0:
            continue
        dot_product = sum(query_vector.get(term, 0.0) * doc_vector.get(term, 0.0) for term in query_vector)
        similarity = dot_product / (query_norm * doc_norm)
        scores.append((doc_id, similarity))

    top_results = nlargest(top_k, scores, key=lambda x: x[1])

    results: list[SearchResult] = []
    for doc_id, score in top_results:
        title = doc_titles.get(doc_id, f"Document {doc_id}")
        results.append(SearchResult(doc_id=doc_id, score=score, title=title))
    return results


def _search_batch_worker(queries: list[str], top_k: int) -> list[list[SearchResult]]:
    if _WORKER_INDEX is None or _WORKER_DOC_TITLES is None:
        raise RuntimeError("Search worker not initialized")
    return [_search_single(query, _WORKER_INDEX, top_k, _WORKER_DOC_TITLES) for query in queries]


def _chunk_queries(queries: list[str], num_workers: int) -> list[list[str]]:
    if not queries:
        return []
    target_chunks = max(num_workers * 4, 1)
    chunk_size = max(1, math.ceil(len(queries) / target_chunks))
    return _chunk_sequence(queries, chunk_size)


# ----------------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------------


def build_tfidf_index_parallel(
    documents: list[Document],
    num_workers: int | None = None,
    chunk_size: int = 500,
) -> ParallelIndexingResult:
    """
    Build TF-IDF inverted index in parallel.

    Returns:
        ParallelIndexingResult with the built index and timing info
    """
    start_time = time.perf_counter()

    index = TFIDFIndex()
    index.num_documents = len(documents)

    if not documents:
        elapsed = time.perf_counter() - start_time
        return ParallelIndexingResult(index=index, elapsed_time=elapsed, num_documents=0, vocabulary_size=0)

    num_workers = _normalize_workers(num_workers, len(documents))

    # Step 1: Tokenize documents and compute term frequencies in parallel
    if num_workers <= 1 or len(documents) <= chunk_size:
        chunk_results = [_process_documents_chunk(documents)]
    else:
        doc_chunks = _chunk_sequence(documents, chunk_size)
        with ProcessPoolExecutor(max_workers=num_workers) as executor:
            chunk_results = list(executor.map(_process_documents_chunk, doc_chunks, chunksize=1))

    # Merge document frequencies and keep chunked TF dicts in order
    df_counts: dict[str, int] = defaultdict(int)
    chunk_doc_tfs: list[dict[int, dict[str, float]]] = []

    for doc_term_freqs, chunk_df in chunk_results:
        chunk_doc_tfs.append(doc_term_freqs)
        for term, count in chunk_df.items():
            df_counts[term] += count

    index.vocabulary = set(df_counts.keys())
    index.document_frequencies = dict(df_counts)

    # Step 2: Compute IDF scores
    N = index.num_documents
    index.idf = {term: math.log(N / df) + 1 for term, df in index.document_frequencies.items()}

    # Step 3: Build inverted index + doc vectors/norms (parallel over chunks)
    if num_workers <= 1 or len(chunk_doc_tfs) <= 1:
        postings_results = [_build_postings_chunk(chunk_doc_tfs[0], index.idf)]
    else:
        with ProcessPoolExecutor(
            max_workers=num_workers,
            initializer=_init_tfidf_worker,
            initargs=(index.idf,),
        ) as executor:
            postings_results = list(executor.map(_build_postings_chunk_worker, chunk_doc_tfs, chunksize=1))

    inverted_index: dict[str, list[tuple[int, float]]] = defaultdict(list)
    doc_vectors: dict[int, dict[str, float]] = {}
    doc_norms: dict[int, float] = {}

    for local_postings, local_doc_vectors, local_doc_norms in postings_results:
        for term, postings in local_postings.items():
            inverted_index[term].extend(postings)
        for doc_id, vector in local_doc_vectors.items():
            doc_vectors[doc_id] = vector
        for doc_id, norm in local_doc_norms.items():
            doc_norms[doc_id] = norm

    # Sort posting lists by score descending (stable) to match sequential behavior
    for term, posting_list in inverted_index.items():
        posting_list.sort(key=lambda x: x[1], reverse=True)

    index.inverted_index = dict(inverted_index)
    index.doc_vectors = doc_vectors
